  Premium: ['प्रीमियम', 'विशिष्टम्', 'प्रीमियम', 'પ્રીમિયમ'],
  Ancient: ['प्राचीन', 'प्राचीनः', 'प्राचीन', 'પ્રાચીન'],
  Medieval: ['मध्यकालीन', 'मध्यकालीनः', 'मध्ययुगीन', 'મધ્યકાલીન'],
  Contemporary: ['समकालीन', 'आधुनिकः', 'समकालीन', 'સમકાલીન'],
  '{what} is for members': ['{what} केवल सदस्यों के लिए है', '{what} केवलं सदस्येभ्यः', '{what} फक्त सदस्यांसाठी आहे', '{what} ફક્ત સભ્યો માટે છે'],
  'This content': ['यह सामग्री', 'इयं सामग्री', 'हा मजकूर', 'આ સામગ્રી'],
  'Upgrade to a Scholar membership to unlock premium texts, audio, presentations and extended AI assistance.': ['प्रीमियम ग्रंथ, ऑडियो, प्रस्तुतियाँ और विस्तृत एआई सहायता के लिए स्कॉलर सदस्यता लें।', 'विशिष्टग्रन्थानां श्रव्याणां प्रस्तुतीनां विस्तृतकृत्रिमबुद्धिसहायतायाः च कृते विद्वत्सदस्यतां स्वीकरोतु।', 'प्रीमियम ग्रंथ, ऑडिओ, सादरीकरणे आणि विस्तारित एआय सहाय्यासाठी स्कॉलर सदस्यत्व घ्या.', 'પ્રીમિયમ ગ્રંથો, ઓડિયો, પ્રસ્તુતિઓ અને વિસ્તૃત એઆઈ સહાય માટે સ્કૉલર સભ્યપદ લો.'],
  'View membership plans': ['सदस्यता योजनाएँ देखें', 'सदस्यतायोजनाः पश्यतु', 'सदस्यत्व योजना पाहा', 'સભ્યપદ યોજનાઓ જુઓ'],
